CREATE TABLE IF NOT EXISTS web_payment_context(pago_id TEXT PRIMARY KEY REFERENCES web_manual_payments(id) DEFERRABLE INITIALLY DEFERRED,plan_codigo TEXT NOT NULL,precio_asignado_centavos BIGINT NOT NULL,periodo_inicio TEXT,periodo_fin TEXT,created_at TEXT NOT NULL DEFAULT panel_now(),CHECK((periodo_inicio IS NULL AND periodo_fin IS NULL) OR(periodo_inicio IS NOT NULL AND periodo_fin IS NOT NULL AND periodo_fin>=periodo_inicio)));



CREATE TABLE IF NOT EXISTS panel_admin_users(
 id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,public_id TEXT NOT NULL UNIQUE,username TEXT NOT NULL UNIQUE,password_hash TEXT NOT NULL,
 role TEXT NOT NULL CHECK(role IN('SUPERADMIN','ADMIN','SOPORTE','LECTURA')),enabled BIGINT NOT NULL DEFAULT 1 CHECK(enabled IN(0,1)),
 auth_version BIGINT NOT NULL DEFAULT 1,must_change_password BIGINT NOT NULL DEFAULT 0,
 created_at TEXT NOT NULL DEFAULT panel_now(),updated_at TEXT NOT NULL DEFAULT panel_now()
);
CREATE TABLE IF NOT EXISTS panel_admin_sessions(token_hash TEXT PRIMARY KEY,admin_id BIGINT NOT NULL REFERENCES panel_admin_users(id) DEFERRABLE INITIALLY DEFERRED,auth_version BIGINT NOT NULL,expires_at BIGINT NOT NULL,created_at TEXT NOT NULL DEFAULT panel_now());
CREATE TABLE IF NOT EXISTS panel_admin_events(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,actor_id BIGINT REFERENCES panel_admin_users(id) DEFERRABLE INITIALLY DEFERRED,target_id BIGINT REFERENCES panel_admin_users(id) DEFERRABLE INITIALLY DEFERRED,accion TEXT NOT NULL,resultado TEXT NOT NULL,motivo TEXT NOT NULL,created_at TEXT NOT NULL DEFAULT panel_now());
CREATE TABLE IF NOT EXISTS panel_auth_attempts(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,bucket TEXT NOT NULL,attempted_at BIGINT NOT NULL);
CREATE INDEX IF NOT EXISTS panel_auth_attempts_bucket ON panel_auth_attempts(bucket,attempted_at);
CREATE TABLE IF NOT EXISTS panel_backup_events(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,accion TEXT NOT NULL,estado TEXT NOT NULL,artifact_name TEXT NOT NULL,retention_count BIGINT NOT NULL,created_at TEXT NOT NULL DEFAULT panel_now());



INSERT INTO web_schema_migrations(version) VALUES('001_web_onboarding'),('002_web_company_states'),('003_web_plans'),('004_web_subscriptions'),('005_web_operations');
CREATE VIEW sqlite_master AS SELECT tablename name,'table'::text type,NULL::text sql FROM pg_tables WHERE schemaname='panel';
CREATE TRIGGER web_subscription_history_immutable BEFORE UPDATE OR DELETE ON web_subscription_history FOR EACH ROW EXECUTE FUNCTION immutable_audit();
CREATE TRIGGER web_manual_payments_immutable BEFORE UPDATE OR DELETE ON web_manual_payments FOR EACH ROW EXECUTE FUNCTION immutable_audit();
CREATE TRIGGER web_payment_context_immutable BEFORE UPDATE OR DELETE ON web_payment_context FOR EACH ROW EXECUTE FUNCTION immutable_audit();
CREATE TRIGGER integration_attempts_immutable BEFORE UPDATE OR DELETE ON integration_attempts FOR EACH ROW EXECUTE FUNCTION immutable_audit();
CREATE TRIGGER panel_admin_events_immutable BEFORE UPDATE OR DELETE ON panel_admin_events FOR EACH ROW EXECUTE FUNCTION immutable_audit();
